// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint64 t1, uint64 t2) public {
        vm.assume(t1 > 1 && t2 > 1);
        if (t1 < t2) {
            uint64 tmp = t1;
            t1 = t2;
            t2 = tmp;
        }
        if (t1 == t2) t1 = t2 + 1; // t1 > t2: the second call happens at a non-later timestamp

        vm.deal(address(this), 20 ether);

        vm.warp(t1);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1);
        require(c.pastBlockTime() == t1);

        vm.roll(block.number + 1);
        vm.warp(t2); // t2 < t1: strictly-earlier timestamp, must be refused by the reference
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: after a successful call, every accepted call strictly increases
        // pastBlockTime; a call at an earlier timestamp must revert, and even if some
        // call were accepted, the stored timestamp could never move backwards.
        assertTrue(!ok2 || c.pastBlockTime() >= t1);
    }
}
